async function resumeSession(){
 const response=await fetch('/auth/session',{credentials:'same-origin',cache:'no-store'});
 if(!response.ok)throw Error('Completa el inicio de sesión en la otra pestaña y pulsa Continuar.');
 const value=await response.json();
 if(!originalSubject||value.subject!==originalSubject)throw Error('Inicia sesión con la misma cuenta para guardar los cambios de este diagrama.');
 document.querySelector('meta[name=csrf-token]').content=value.csrf;
}
async function api(path='',options={},retried=false,base=API){
 let response;try{response=await fetch(base+path,{credentials:'same-origin',...options,headers:{'Content-Type':'application/json','X-CSRF-Token':document.querySelector('meta[name=csrf-token]')?.content||'',...options.headers}});}catch{const fault={code:'KOD-NET-001',reference:'cli-'+crypto.randomUUID()};reportFault(fault);const error=new Error('No se pudo conectar. Conserva abierta esta pestaña.');error.code=fault.code;throw error;}
 if(!response.ok){let body={};try{body=await response.json();}catch{}
  if(response.status===403&&body.code==='csrf_invalid'&&!retried){try{await resumeSession();return api(path,options,true,base);}catch{window.dispatchEvent(new Event('koodaria:auth-required'));}}
  if(response.status===401){
   if(!dirty&&!activeSaver?.isDirty())window.location.replace(loginUrl());
   else window.dispatchEvent(new Event('koodaria:auth-required'));
  }
  const error=new Error(body.error||'No se pudo conectar. Tus cambios siguen en esta pestaña.');error.status=response.status;error.code=body.error_code||'KOD-REQ-001';error.reference=body.reference||'cli-'+crypto.randomUUID();reportFault({code:error.code,reference:error.reference,message:error.message,action:body.action});throw error;
 }
 if(response.status===204)return null;if(options.responseType==='blob')return response.blob();try{return await response.json();}catch{const fault={code:'KOD-NET-002',reference:'cli-'+crypto.randomUUID()};reportFault(fault);throw new Error('La respuesta del servidor no se pudo interpretar.');}
}
