const beforeUnload=e=>{if(dirty){e.preventDefault();e.returnValue='';}};
window.addEventListener('beforeunload',beforeUnload);
export function mount(element){unmount();activeRoot=createRoot(element);activeRoot.render(<ReactFlowProvider><Workspace/><ErrorCenter/></ReactFlowProvider>);}
export function mountStandards(element){unmount();activeRoot=createRoot(element);activeRoot.render(<><ErrorCenter/><StandardsWorkspace api={standardsApi} Glyph={Glyph} onDirty={v=>{dirty=v;}} SessionRecovery={SessionRecovery} resumeSession={resumeSession} registerLeave={handler=>{leaveHandler=handler;}}/></>);}
export function unmount(){if(activeRoot){activeRoot.unmount();activeRoot=null;}activeSaver=null;leaveHandler=null;dirty=false;}

export function hasUnsavedChanges(){return !!activeRoot&&(dirty||!!activeSaver?.isDirty());}

export function requestLeave(){return leaveHandler?leaveHandler():Promise.resolve(!hasUnsavedChanges()||confirm('Todavía hay cambios sin guardar. ¿Salir del editor?'));}

export function mountDiscovery(element){unmount();activeRoot=createRoot(element);activeRoot.render(<><ErrorCenter/><DiscoveryWorkspace onDirty={v=>{dirty=v;}} registerLeave={handler=>{leaveHandler=handler;}}/></>);}
